   if(!request.headers.get('content-type')?.startsWith('application/json'))return json({error:'JSON required'},415);
   const body=await request.text();if(body.length>16000)return json({error:'Basket too large'},413);
   let input,lines;try{input=JSON.parse(body);lines=validateCart(input.items)}catch(e){return json({error:e.message},400)}
   const form=new URLSearchParams({mode:'payment',success_url:url.origin+'/checkout-result.html?session_id={CHECKOUT_SESSION_ID}',cancel_url:url.origin+'/cart?checkout=cancelled','shipping_address_collection[allowed_countries][0]':'IE','shipping_options[0][shipping_rate_data][type]':'fixed_amount','shipping_options[0][shipping_rate_data][fixed_amount][amount]':'700','shipping_options[0][shipping_rate_data][fixed_amount][currency]':'eur','shipping_options[0][shipping_rate_data][display_name]':'Delivery within Ireland','metadata[shop]':'sudsys-soaps-sandbox','custom_text[submit][message]':'TEST CHECKOUT ONLY. No real payment or order will be taken.'});
   lines.forEach(({p,v,qty,variant},i)=>{
    const k='line_items['+i+']';form.set(k+'[quantity]',String(qty));form.set(k+'[price_data][currency]','eur');form.set(k+'[price_data][unit_amount]',String(v.price));form.set(k+'[price_data][product_data][name]',p.title);
    if(v.options[0]!=='Default Title')form.set(k+'[price_data][product_data][description]',v.options.join(' / '));
    form.set(k+'[price_data][product_data][metadata][handle]',p.handle);form.set(k+'[price_data][product_data][metadata][variant]',String(variant));
   });
